#ROUTE CRITERIA
#the criteria for one route, picked by its route name ("service_pricing", "business_operations", "escalation", ...), None when the name isn't one of them
def criteria(route: str) -> str:
    if(route == "service_pricing"):
        return SERVICE_PRICING_INSTRUCTIONS

    elif(route == "business_operations"):
        return BUSINESS_OPERATIONS_INSTRUCTIONS

    elif(route == "services_req_humans"):
        return SERVICES_REQ_HUMANS_INSTRUCTIONS

    elif(route == "booking_service_acknowledge"):
        return BOOKING_SERVICE_ACKNOWLEDGE_INSTRUCTIONS

    elif(route == "escalation"):
        return ESCALATION_INSTRUCTIONS

    elif(route == "general_text"):
        return GENERAL_TEXT_INSTRUCTIONS

    elif(route == "phone_call"):
        return PHONE_CALL_INSTRUCTIONS

    elif(route == "end_conversation"):
        return END_CONVERSATION_INSTRUCTIONS


